st=open('ryzeapp/app/src/main/java/au/buzz/ryzewave/workout/StrideCalibration.kt').read()
def ids(b):
    m=re.search(b+r'\s*=\s*setOf\((.*?)\n    \)', st, re.S)
    return set(int(x,16) for x in re.findall(r'0x([0-9A-Fa-f]{2})', m.group(1))) if m else set()
